"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ReactNode, useEffect, useId, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One task in a checklist. */
export interface ChecklistItem {
  id: string;
  label: string;
  done: boolean;
}

/** Props for a checklist. Pass `items` to control it, or `defaultItems` to let it hold its own state. */
export interface ChecklistProps {
  items?: ChecklistItem[];
  defaultItems?: ChecklistItem[];
  onItemsChange?: (items: ChecklistItem[]) => void;
  /** Names the list for screen readers and shows above it. */
  label: ReactNode;
  className?: string;
}

// A ticked task stays in place this long, so the person sees the tick land
// before the task moves below the open ones.
const SETTLE_MS = 450;
// Damping 40 is 2 × √400: critically damped, so a task slides into place without overshoot.
const MOVE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const DRAW: Transition = { type: "spring", duration: 0.3, bounce: 0 };
const INSTANT: Transition = { duration: 0 };

/**
 * A list of tasks to tick off. A ticked task greys out, then slides below the
 * open tasks, so what is left to do stays at the top. Unticking brings it back.
 */
export function Checklist({ items, defaultItems = [], onItemsChange, label, className }: ChecklistProps) {
  const [ownItems, setOwnItems] = useState(defaultItems);
  const current = items ?? ownItems;
  // Where each task sits can lag its tick by SETTLE_MS, so it is tracked apart from `done`.
  const [placedDone, setPlacedDone] = useState(() => new Map(current.map((item) => [item.id, item.done])));
  // Each pending move remembers the state it settles to, so a change of mind restarts the wait.
  const timers = useRef(new Map<string, { timer: number; done: boolean }>());
  const latest = useRef(current);
  const inputs = useRef(new Map<string, HTMLInputElement>());
  const refocus = useRef<string | null>(null);
  const reduceMotion = useReducedMotion();
  const labelId = useId();

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach(({ timer }) => window.clearTimeout(timer));
  }, []);

  // A task moves once its tick has settled, whoever ticked it: this list, a
  // "mark all done" in the parent, or a sync. The move reads the task as it is
  // then, so a parent that refuses a change leaves the row where it was.
  useEffect(() => {
    latest.current = current;
    for (const item of current) {
      const pending = timers.current.get(item.id);
      if (pending?.done === item.done) continue;
      if (pending) window.clearTimeout(pending.timer);
      timers.current.delete(item.id);
      // Back where it already sits: nothing to move.
      if ((placedDone.get(item.id) ?? item.done) === item.done) continue;
      const timer = window.setTimeout(() => {
        timers.current.delete(item.id);
        const now = latest.current.find((task) => task.id === item.id);
        if (!now) return;
        const focused = [...inputs.current].find(([, input]) => input === document.activeElement);
        refocus.current = focused ? focused[0] : null;
        setPlacedDone((placed) => new Map(placed).set(item.id, now.done));
      }, SETTLE_MS);
      timers.current.set(item.id, { timer, done: item.done });
    }
  }, [current, placedDone]);

  // Moving a row can drop focus from its checkbox, so a keyboard user who was
  // on it gets it back after the move.
  useLayoutEffect(() => {
    const id = refocus.current;
    refocus.current = null;
    const input = id ? inputs.current.get(id) : undefined;
    if (input && document.activeElement !== input) input.focus({ preventScroll: true });
  }, [placedDone]);

  const isPlacedDone = (item: ChecklistItem) => placedDone.get(item.id) ?? item.done;
  const ordered = [...current.filter((item) => !isPlacedDone(item)), ...current.filter(isPlacedDone)];
  const doneCount = current.filter((item) => item.done).length;

  const toggle = (id: string) => {
    const next = current.map((item) => (item.id === id ? { ...item, done: !item.done } : item));
    if (items === undefined) setOwnItems(next);
    onItemsChange?.(next);
  };

  return (
    <div className={cn("flex w-full max-w-sm flex-col gap-2", className)}>
      <div className="flex items-baseline justify-between gap-4 px-2 text-sm">
        <span id={labelId} className="font-medium text-foreground">
          {label}
        </span>
        <span role="status" className="tabular-nums text-muted-foreground">
          {doneCount} of {current.length} done
        </span>
      </div>
      <ul aria-labelledby={labelId} className="flex flex-col">
        {ordered.map((item) => (
          <motion.li key={item.id} layout={reduceMotion ? false : "position"} transition={MOVE}>
            <label className="flex min-h-11 cursor-pointer items-center gap-3 rounded-xl px-2 hover:bg-muted motion-safe:transition-colors sm:min-h-9">
              <span className="relative grid size-5 shrink-0 place-items-center">
                <input
                  ref={(node) => {
                    if (node) inputs.current.set(item.id, node);
                    else inputs.current.delete(item.id);
                  }}
                  type="checkbox"
                  checked={item.done}
                  onChange={() => toggle(item.id)}
                  className="absolute inset-0 size-full cursor-pointer appearance-none rounded-md border border-muted-foreground/70 bg-background outline-none checked:border-primary checked:bg-primary focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition-colors"
                />
                <svg
                  viewBox="0 0 16 16"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  aria-hidden="true"
                  className="pointer-events-none relative size-3.5 text-primary-foreground"
                >
                  <motion.path
                    d="m3.5 8.5 3 3 6-6.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    initial={false}
                    animate={{ pathLength: item.done ? 1 : 0 }}
                    transition={reduceMotion ? INSTANT : DRAW}
                  />
                </svg>
              </span>
              <span
                className={cn(
                  // The line is always there and only its colour changes, so it fades in and out.
                  "min-w-0 text-sm line-through decoration-1 motion-safe:transition-colors motion-safe:duration-300",
                  item.done ? "text-muted-foreground decoration-muted-foreground" : "text-foreground decoration-transparent",
                )}
              >
                {item.label}
              </span>
            </label>
          </motion.li>
        ))}
      </ul>
    </div>
  );
}
